17	/* rb_create() must hand back a live, empty tree -- the baseline every
18	 * other test builds on. */
19	static void test_create_returns_empty_tree(void)
20	{
21	    printf("test_create_returns_empty_tree\n");
22	    rbtree_t *t = rb_create(NULL);
23	    CHECK(t != NULL, "rb_create returned NULL");
24	    CHECK(rb_size(t) == 0, "fresh tree should have size 0");
25	    rb_destroy(t);
26	}
