28	/* The most basic contract: a value inserted under a key must be
29	 * retrievable under that same key. */
30	static void test_insert_then_find_roundtrip(void)
31	{
32	    printf("test_insert_then_find_roundtrip\n");
33	    rbtree_t *t = rb_create(NULL);
34	    int value = 42;
35	
36	    CHECK(rb_insert(t, "alpha", &value) == 0, "insert should succeed");
37	    CHECK(rb_find(t, "alpha") == &value, "find should return the inserted value");
38	    CHECK(rb_size(t) == 1, "size should be 1 after one insert");
39	
40	    rb_destroy(t);
41	}
42	
43	/* rb_find must report absence with NULL rather than crashing or returning
44	 * a stale pointer, both on an empty tree and once other keys exist. */
45	static void test_find_absent_key_returns_null(void)
46	{
47	    printf("test_find_absent_key_returns_null\n");
48	    rbtree_t *t = rb_create(NULL);
49	    int value = 1;
50	
51	    CHECK(rb_find(t, "missing") == NULL, "find on empty tree should return NULL");
52	
53	    rb_insert(t, "present", &value);
54	    CHECK(rb_find(t, "missing") == NULL, "find for a never-inserted key should return NULL");
55	
56	    rb_destroy(t);
57	}
